import type { MetadataRoute } from "next"
import { SITE } from "@/lib/seo/config"

/**
 * Web app manifest (SEO-001). Served at /manifest.webmanifest, which 404s today.
 *
 * Only icons that exist are listed. A manifest referencing a missing file is
 * worse than no manifest: the install prompt fails and Lighthouse reports the
 * whole PWA section as broken. Each entry below is generated by
 * `scripts/generate-icons.mjs` and committed.
 *
 * `screenshots` is deliberately absent. The reference configuration this was
 * modelled on listed `/screenshot-desktop.png` and `/screenshot-mobile.png`,
 * neither of which exists in this repository; listing them would break the
 * richer install UI rather than enable it.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: SITE.fullName,
    short_name: SITE.shortName,
    description:
      "Online courses and verifiable certificates from BwengePlus. Browse open MOOC courses and institution-led programmes, and learn at your own pace.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait-primary",
    background_color: SITE.backgroundColor,
    theme_color: SITE.themeColor,
    lang: "en",
    dir: "ltr",
    categories: ["education"],
    icons: [
      {
        src: "/icons/icon-192.png",
        sizes: "192x192",
        type: "image/png",
        purpose: "any",
      },
      {
        src: "/icons/icon-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "any",
      },
      /*
       * Separate maskable entry with its own artwork.
       * Declaring the same file as "any maskable" is a common mistake: a
       * launcher crops a maskable icon to a circle, so a glyph drawn to the
       * edges loses its extremities. This file has the extra padding.
       */
      {
        src: "/icons/icon-maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
    shortcuts: [
      {
        name: "Browse courses",
        short_name: "Courses",
        url: "/courses",
      },
      {
        name: "Verify a certificate",
        short_name: "Verify",
        url: "/certificates",
      },
    ],
  }
}
